import foto1 from '../img/sec/01.jpg';
import foto2 from '../img/sec/02.jpg';

export default function Main() {
return (
<div className='main'>
{/* <div className="_container"> */}
  <div className="main__row">
    <div className="main__row-left">
      <img src={foto1} alt="" />
    </div>
    <div className="main__row-right">
    <img src={foto2} alt="" />
    </div>
  </div>
{/* </div> */}
 </div>
);
}
